#!/usr/bin/env node
/**
 * Guard tests for hooks/lib/sql-target.js (through hooks/guard-shell.js): a SQL Server or MySQL host
 * given by environment variable, and an abbreviated `Invoke-Sqlcmd -ServerInstance`. Zero dependencies.
 *
 *   node --test tools/sql-target-bypass.test.mjs
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const HOOK = join(ROOT, 'hooks', 'guard-shell.js');
const home = mkdtempSync(join(tmpdir(), 'sqlbypass-home-'));
const cwd = mkdtempSync(join(tmpdir(), 'sqlbypass-cwd-'));
mkdirSync(join(home, '.claude'));
writeFileSync(join(home, '.claude', 'db-targets.json'), JSON.stringify({ devHosts: ['localhost', 'dev-db.example.test'] }));
process.on('exit', () => {
  for (const dir of [home, cwd]) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } }
});

function run(command) {
  const env = { ...process.env, HOME: home, USERPROFILE: home };
  for (const k of ['PGHOST', 'SQLCMDSERVER', 'MYSQL_HOST']) delete env[k];
  const r = spawnSync(process.execPath, [HOOK], {
    input: JSON.stringify({ tool_name: 'Bash', tool_input: { command }, cwd }), encoding: 'utf8', env,
  });
  assert.equal(r.status, 0, 'the hook must always exit 0');
  if (!r.stdout.trim()) return 'approve';
  return JSON.parse(r.stdout).hookSpecificOutput.permissionDecision;
}

const PROD = 'prod-db.example.test';
const DEV = 'dev-db.example.test';

const denied = [
  // F4: SQL Server host variable, per shell spelling
  `SQLCMDSERVER=${PROD} sqlcmd -Q "select 1"`,
  `$env:SQLCMDSERVER='${PROD}'; sqlcmd -Q "select 1"`,
  `$env:SQLCMDSERVER = "${PROD}"; sqlcmd -Q "select 1"`,
  `export SQLCMDSERVER=${PROD} && sqlcmd -Q "select 1"`,
  `set SQLCMDSERVER=${PROD}&& sqlcmd -Q "select 1"`,
  `env SQLCMDSERVER=${PROD} sqlcmd -Q "select 1"`,
  `SQLCMDSERVER="tcp:${PROD},1433" sqlcmd -Q "select 1"`,
  `sqlcmd -Q "select 1" # SQLCMDSERVER=${PROD}`,
  `SQLCMDSERVER=${PROD} bcp t out f.dat -c`,
  // F4: MySQL host variable, per shell spelling
  `MYSQL_HOST=${PROD} mysql -e "select 1"`,
  `$env:MYSQL_HOST='${PROD}'; mysql -e "select 1"`,
  `export MYSQL_HOST=${PROD}; mysql -e "select 1"`,
  `set MYSQL_HOST=${PROD}&& mysql -e "select 1"`,
  `env MYSQL_HOST="${PROD}" mariadb -e "select 1"`,
  `MYSQL_HOST=${PROD} mysqldump db`,
  // F5: -ServerInstance prefixes, case, colon form
  `Invoke-Sqlcmd -ServerInstance ${PROD} -Query "select 1"`,
  `Invoke-Sqlcmd -ServerI ${PROD} -Query "select 1"`,
  `Invoke-Sqlcmd -Serv ${PROD} -Query "select 1"`,
  `Invoke-Sqlcmd -Ser ${PROD} -Query "select 1"`,
  `Invoke-Sqlcmd -SERVERINST ${PROD} -Query "select 1"`,
  `Invoke-Sqlcmd -serveri:${PROD} -Query "select 1"`,
  `Invoke-Sqlcmd -ServerI:'${PROD}' -Query "select 1"`,
  `Invoke-Sqlcmd -ServerInstance:${PROD} -Query "select 1"`,
  `Invoke-Sqlcmd -Query "select 1" -ServerI ${PROD}`,
  // F5: -ConnectionString prefixes (decides the target too)
  `Invoke-Sqlcmd -ConnectionString "Server=${PROD};Database=x"`,
  `Invoke-Sqlcmd -ConnectionS "Server=${PROD};Database=x"`,
  `Invoke-Sqlcmd -ConnectionStr:"Server=${PROD};Database=x"`,
  // A readable dev host next to a reassignment the guard cannot read
  `$env:SQLCMDSERVER='localhost'; Set-Item env:SQLCMDSERVER ${PROD}; sqlcmd -Q "select 1"`,
  `$env:MYSQL_HOST='localhost'; [Environment]::SetEnvironmentVariable('MYSQL_HOST','${PROD}'); mysql -e "select 1"`,
  `$env:SQLCMDSERVER='localhost'; $env:SQLCMDSERVER+='x'; sqlcmd -Q "select 1"`,
  `$env:SQLCMDSERVER+='x'; sqlcmd -Q "select 1"`,
  `$env:PGHOST='localhost'; Set-Item env:PGHOST ${PROD}; psql -c "select 1"`,
];
denied.forEach((command, i) => {
  test(`Given bypass variant ${i + 1} (${command}), When the guard runs, Then it is denied`, () => {
    // Given the command above and a registry listing only ${DEV}
    // When
    const decision = run(command);
    // Then
    assert.equal(decision, 'deny', command);
  });
});

const allowed = [
  `SQLCMDSERVER=${DEV} sqlcmd -Q "select 1"`,
  `$env:SQLCMDSERVER='localhost'; sqlcmd -Q "select 1"`,
  `sqlcmd -S ${DEV} -Q "select 1"`,
  `sqlcmd -Q "select 1"`,
  `MYSQL_HOST=${DEV} mysql -e "select 1"`,
  `MYSQL_HOST=127.0.0.1 mysql -e "select 1"`,
  `mysql -h ${DEV} -e "select 1"`,
  `mysql -e "select 1"`,
  `Invoke-Sqlcmd -ServerI ${DEV} -Query "select 1"`,
  `Invoke-Sqlcmd -Ser:localhost -Query "select 1"`,
  `Invoke-Sqlcmd -Query "select 1" -Database master`,
  `Invoke-Sqlcmd -SeverityLevel 10 -Query "select 1"`,
  `Invoke-Sqlcmd -ConnectionTimeout 5 -Query "select 1"`,
  `PGHOST=${DEV} psql -c "select 1"`,
];
allowed.forEach((command, i) => {
  test(`Given local or dev target ${i + 1} (${command}), When the guard runs, Then it is not denied`, () => {
    // Given the command above and a registry listing ${DEV}
    // When
    const decision = run(command);
    // Then
    assert.notEqual(decision, 'deny', command);
  });
});

test('Given a non-dev host in a variable the guard can read, When the guard runs, Then the reason names the host', () => {
  // Given
  const command = `MYSQL_HOST=${PROD} mysql -e "select 1"`;
  // When
  const r = spawnSync(process.execPath, [HOOK], {
    input: JSON.stringify({ tool_name: 'Bash', tool_input: { command }, cwd }),
    encoding: 'utf8', env: { ...process.env, HOME: home, USERPROFILE: home },
  });
  // Then
  assert.match(JSON.parse(r.stdout).hookSpecificOutput.permissionDecisionReason, /prod-db\.example\.test/);
});
